#!/usr/bin/env node
/**
 * Applies patches for unrs-resolver to fix Jest 30 compatibility on Windows
 *
 * The unrs-resolver native binding cannot load on Windows due to missing
 * unrs_resolver_napi.dll. This script patches unrs-resolver to use a
 * pure-JavaScript fallback resolver.
 *
 * Run this after `npm install` or as a postinstall hook.
 */

const fs = require('fs');
const path = require('path');

const PATCHED_INDEX_JS = `// prettier-ignore
/* eslint-disable */
// @ts-nocheck
/* auto-generated by NAPI-RS - PATCHED to use Node's resolver when native binding fails */

const { readFileSync } = require('node:fs')
const path = require('node:path')
const Module = require('node:module')
let nativeBinding = null
const loadErrors = []

const isMusl = () => {
  let musl = false
  if (process.platform === 'linux') {
    musl = isMuslFromFilesystem()
    if (musl === null) {
      musl = isMuslFromReport()
    }
    if (musl === null) {
      musl = isMuslFromChildProcess()
    }
  }
  return musl
}

const isFileMusl = (f) => f.includes('libc.musl-') || f.includes('ld-musl-')

const isMuslFromFilesystem = () => {
  try {
    return readFileSync('/usr/bin/ldd', 'utf-8').includes('musl')
  } catch {
    return null
  }
}

const isMuslFromReport = () => {
  let report = null
  if (typeof process.report?.getReport === 'function') {
    process.report.excludeNetwork = true
    report = process.report.getReport()
  }
  if (!report) {
    return null
  }
  if (report.header && report.header.glibcVersionRuntime) {
    return false
  }
  if (Array.isArray(report.sharedObjects)) {
    if (report.sharedObjects.some(isFileMusl)) {
      return true
    }
  }
  return null
}

const isMuslFromChildProcess = () => {
  try {
    return require('child_process').execSync('ldd --version', { encoding: 'utf8' }).includes('musl')
  } catch (e) {
    return false
  }
}

function requireNative() {
  if (process.env.NAPI_RS_NATIVE_LIBRARY_PATH) {
    try {
      return require(process.env.NAPI_RS_NATIVE_LIBRARY_PATH);
    } catch (err) {
      loadErrors.push(err)
    }
  }
  // PATCHED: Try to load the shim fallback before throwing
  try {
    const shim = require('./unrs-shim.js')
    return shim
  } catch (e) {
    // Shim will be created, continue with normal loading
  }
  if (process.platform === 'android') {
    if (process.arch === 'arm64') {
      try {
        return require('./resolver.android-arm64.node')
      } catch (e) {
        loadErrors.push(e)
      }
      try {
        const binding = require('@unrs/resolver-binding-android-arm64')
        const bindingPackageVersion = require('@unrs/resolver-binding-android-arm64/package.json').version
        if (bindingPackageVersion !== '1.12.2' && process.env.NAPI_RS_ENFORCE_VERSION_CHECK && process.env.NAPI_RS_ENFORCE_VERSION_CHECK !== '0') {
          throw new Error(\`Native binding package version mismatch, expected 1.12.2 but got \${bindingPackageVersion}. You can reinstall dependencies to fix this issue.\`)
        }
        return binding
      } catch (e) {
        loadErrors.push(e)
      }
    } else if (process.arch === 'arm') {
      try {
        return require('./resolver.android-arm-eabi.node')
      } catch (e) {
        loadErrors.push(e)
      }
      try {
        const binding = require('@unrs/resolver-binding-android-arm-eabi')
        const bindingPackageVersion = require('@unrs/resolver-binding-android-arm-eabi/package.json').version
        if (bindingPackageVersion !== '1.12.2' && process.env.NAPI_RS_ENFORCE_VERSION_CHECK && process.env.NAPI_RS_ENFORCE_VERSION_CHECK !== '0') {
          throw new Error(\`Native binding package version mismatch, expected 1.12.2 but got \${bindingPackageVersion}. You can reinstall dependencies to fix this issue.\`)
        }
        return binding
      } catch (e) {
        loadErrors.push(e)
      }
    } else {
      loadErrors.push(new Error(\`Unsupported architecture on Android \${process.arch}\`))
    }
  } else if (process.platform === 'win32') {
    try {
      return require('./resolver.win32-x64-msvc.node')
    } catch (e) {
      loadErrors.push(e)
    }
  } else if (process.platform === 'darwin') {
    if (process.arch === 'arm64') {
      try {
        return require('./resolver.darwin-arm64.node')
      } catch (e) {
        loadErrors.push(e)
      }
      try {
        const binding = require('@unrs/resolver-binding-darwin-arm64')
        const bindingPackageVersion = require('@unrs/resolver-binding-darwin-arm64/package.json').version
        if (bindingPackageVersion !== '1.12.2' && process.env.NAPI_RS_ENFORCE_VERSION_CHECK && process.env.NAPI_RS_ENFORCE_VERSION_CHECK !== '0') {
          throw new Error(\`Native binding package version mismatch, expected 1.12.2 but got \${bindingPackageVersion}. You can reinstall dependencies to fix this issue.\`)
        }
        return binding
      } catch (e) {
        loadErrors.push(e)
      }
    } else if (process.arch === 'x64') {
      try {
        return require('./resolver.darwin-x64.node')
      } catch (e) {
        loadErrors.push(e)
      }
      try {
        const binding = require('@unrs/resolver-binding-darwin-x64')
        const bindingPackageVersion = require('@unrs/resolver-binding-darwin-x64/package.json').version
        if (bindingPackageVersion !== '1.12.2' && process.env.NAPI_RS_ENFORCE_VERSION_CHECK && process.env.NAPI_RS_ENFORCE_VERSION_CHECK !== '0') {
          throw new Error(\`Native binding package version mismatch, expected 1.12.2 but got \${bindingPackageVersion}. You can reinstall dependencies to fix this issue.\`)
        }
        return binding
      } catch (e) {
        loadErrors.push(e)
      }
    }
  } else {
    loadErrors.push(new Error(\`Unsupported OS: \${process.platform}, architecture: \${process.arch}\`))
  }
}

/**
 * Node.js fallback resolver (Pure-JS implementation using Node's built-in module resolution).
 * Used when the native unrs-resolver binding cannot be loaded.
 */
class NodeResolverFactory {
  constructor(options) {
    this.options = options
  }

  sync(basedir, filePath) {
    try {
      // Built-in modules
      if (Module.isBuiltin(filePath)) {
        return { path: filePath }
      }

      // Absolute paths
      if (path.isAbsolute(filePath)) {
        if (require('fs').existsSync(filePath)) {
          return { path: filePath }
        }
        return { error: \`ENOENT: no such file or directory, open '\${filePath}'\` }
      }

      // Relative paths - must start with './' or '../' (not just '.')
      if (filePath.startsWith('./') || filePath.startsWith('../')) {
        const fs = require('fs')
        let resolved = path.resolve(basedir, filePath)

        // Check if it's a file directly
        if (fs.existsSync(resolved) && fs.statSync(resolved).isFile()) {
          return { path: resolved }
        }

        // Check if it's a directory with index file
        if (fs.existsSync(resolved) && fs.statSync(resolved).isDirectory()) {
          for (const indexFile of ['index.js', 'index.ts', 'index.mjs']) {
            const indexPath = path.join(resolved, indexFile)
            if (fs.existsSync(indexPath)) {
              return { path: indexPath }
            }
          }
          // Check for package.json main field
          const packageJsonPath = path.join(resolved, 'package.json')
          if (fs.existsSync(packageJsonPath)) {
            try {
              const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'))
              const main = pkg.main
              if (main && typeof main === 'string') {
                const mainPath = path.resolve(resolved, main)
                if (fs.existsSync(mainPath) && fs.statSync(mainPath).isFile()) {
                  return { path: mainPath }
                }
                for (const ext of ['.js', '.ts', '.tsx']) {
                  const mainPathWithExt = mainPath + ext
                  if (fs.existsSync(mainPathWithExt)) {
                    return { path: mainPathWithExt }
                  }
                }
              }
            } catch (e) {}
          }
        }

        // Handle ESM .js -> .ts mapping
        if (resolved.endsWith('.js')) {
          const resolvedTs = resolved.slice(0, -3) + '.ts'
          if (fs.existsSync(resolvedTs) && fs.statSync(resolvedTs).isFile()) {
            return { path: resolvedTs }
          }
        }

        // Try with common extensions
        for (const ext of ['.ts', '.tsx', '.js', '.json']) {
          const extPath = resolved + ext
          if (fs.existsSync(extPath) && fs.statSync(extPath).isFile()) {
            return { path: extPath }
          }
        }

        // Windows path handling
        if (process.platform === 'win32') {
          resolved = resolved.replace(/\\\\/g, '/')
          if (fs.existsSync(resolved) && fs.statSync(resolved).isFile()) {
            return { path: resolved }
          }
          if (fs.existsSync(resolved) && fs.statSync(resolved).isDirectory()) {
            for (const indexFile of ['index.js', 'index.ts', 'index.mjs']) {
              const indexPath = path.join(resolved, indexFile)
              if (fs.existsSync(indexPath)) {
                return { path: indexPath }
              }
            }
            const packageJsonPath = path.join(resolved, 'package.json')
            if (fs.existsSync(packageJsonPath)) {
              try {
                const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'))
                const main = pkg.main
                if (main && typeof main === 'string') {
                  const mainPath = path.join(resolved, main)
                  if (fs.existsSync(mainPath) && fs.statSync(mainPath).isFile()) {
                    return { path: mainPath }
                  }
                  for (const ext of ['.js', '.ts', '.tsx']) {
                    const mainPathWithExt = mainPath + ext
                    if (fs.existsSync(mainPathWithExt)) {
                      return { path: mainPathWithExt }
                    }
                  }
                }
              } catch (e) {}
            }
          }
          if (resolved.endsWith('.js')) {
            const resolvedTs = resolved.slice(0, -3) + '.ts'
            if (fs.existsSync(resolvedTs) && fs.statSync(resolvedTs).isFile()) {
              return { path: resolvedTs }
            }
          }
          for (const ext of ['.ts', '.tsx', '.js', '.json']) {
            const extPath = resolved + ext
            if (fs.existsSync(extPath) && fs.statSync(extPath).isFile()) {
              return { path: extPath }
            }
          }
        }
        return { error: \`ENOENT: no such file or directory\` }
      }

      // Bare specifiers - use require.resolve with paths hint
      const normalizedBasedir = process.platform === 'win32' && path.isAbsolute(basedir)
        ? basedir.replace(/\\\\/g, '/')
        : basedir
      const resolved = Module._resolveFilename(filePath, {
        id: filePath,
        filename: path.join(normalizedBasedir, 'package.json'),
        paths: Module._nodeModulePaths(normalizedBasedir),
      }, undefined, true)

      return { path: resolved }
    } catch (err) {
      if (err.code === 'MODULE_NOT_FOUND') {
        return { error: err.message }
      }
      throw err
    }
  }

  _sync(basedir, filePath) {
    return this.sync(basedir, filePath)
  }

  async syncAsync(basedir, filePath) {
    return this._sync(basedir, filePath)
  }

  cloneWithOptions(newOptions) {
    return new NodeResolverFactory(newOptions)
  }

  clearCache() {}
}

// Try to load native binding, fall back to Node resolver
let bindings
nativeBinding = requireNative()

if (!nativeBinding) {
  // PATCHED: Fall back to Node's built-in resolver
  nativeBinding = {
    ResolverFactory: NodeResolverFactory,
    EnforceExtension: { ERROR: 'error', WARN: 'warn', IGNORE: 'ignore' },
    ModuleType: {
      FILE: 'file', DIR: 'dir', EXTERN: 'extern',
      SHARED_LIBRARY: 'shared_library', NODE_MODULE: 'node_module', JSON: 'json'
    },
    builtins: Object.freeze([
      'assert', 'buffer', 'child_process', 'cluster', 'console', 'constants',
      'crypto', 'dgram', 'dns', 'domain', 'events', 'fs', 'http', 'https',
      'module', 'net', 'os', 'path', 'perf_hooks', 'process', 'punycode',
      'querystring', 'stream', 'string_decoder', 'sys', 'timers', 'tls',
      'tty', 'url', 'util', 'v8', 'vm', 'worker_threads',
      'node:assert', 'node:buffer', 'node:child_process', 'node:cluster',
      'node:console', 'node:constants', 'node:crypto', 'node:dgram',
      'node:dns', 'node:domain', 'node:events', 'node:fs', 'node:http',
      'node:https', 'node:module', 'node:net', 'node:os', 'node:perf_hooks',
      'node:process', 'node:punycode', 'node:querystring', 'node:stream',
      'node:string_decoder', 'node:sys', 'node:timers', 'node:tls',
      'node:tty', 'node:url', 'node:util', 'node:v8', 'node:vm',
      'node:worker_threads'
    ]),
    sync: (basedir, filePath) => {
      const factory = new NodeResolverFactory({ basedir })
      return factory.sync(basedir, filePath)
    },
    async: async (basedir, filePath) => {
      const factory = new NodeResolverFactory({ basedir })
      return factory.syncAsync(basedir, filePath)
    },
    clearCache: () => {}
  }
}

module.exports = nativeBinding
module.exports.ResolverFactory = nativeBinding.ResolverFactory
module.exports.EnforceExtension = nativeBinding.EnforceExtension
module.exports.ModuleType = nativeBinding.ModuleType
module.exports.sync = nativeBinding.sync

if (process.versions.pnp) {
  process.env.UNRS_RESOLVER_YARN_PNP = '1'
}
`;

const SHIM_JS = `// Pure-JavaScript shim for unrs-resolver
// Created as fallback when native binding cannot be loaded

class NodeResolverFactory {
  constructor(options) { this.options = options }
  sync(basedir, filePath) {
    try {
      const Module = require('node:module')
      const path = require('node:path')
      const fs = require('node:fs')

      if (Module.isBuiltin(filePath)) {
        return { path: filePath }
      }

      if (path.isAbsolute(filePath)) {
        if (fs.existsSync(filePath)) {
          return { path: filePath }
        }
        return { error: \`ENOENT: no such file or directory, open '\${filePath}'\` }
      }

      if (filePath.startsWith('./') || filePath.startsWith('../')) {
        let resolved = path.resolve(basedir, filePath)
        if (fs.existsSync(resolved) && fs.statSync(resolved).isFile()) {
          return { path: resolved }
        }
        if (fs.existsSync(resolved) && fs.statSync(resolved).isDirectory()) {
          for (const indexFile of ['index.js', 'index.ts', 'index.mjs']) {
            const indexPath = path.join(resolved, indexFile)
            if (fs.existsSync(indexPath)) {
              return { path: indexPath }
            }
          }
          try {
            const pkg = JSON.parse(fs.readFileSync(path.join(resolved, 'package.json'), 'utf8'))
            const main = pkg.main
            if (main && typeof main === 'string') {
              const mainPath = path.join(resolved, main)
              if (fs.existsSync(mainPath) && fs.statSync(mainPath).isFile()) {
                return { path: mainPath }
              }
            }
          } catch (e) {}
        }
        if (resolved.endsWith('.js')) {
          const resolvedTs = resolved.slice(0, -3) + '.ts'
          if (fs.existsSync(resolvedTs)) {
            return { path: resolvedTs }
          }
        }
        for (const ext of ['.ts', '.tsx', '.js', '.json']) {
          if (fs.existsSync(resolved + ext)) {
            return { path: resolved + ext }
          }
        }
        return { error: 'ENOENT: no such file or directory' }
      }

      const normalizedBasedir = process.platform === 'win32' && path.isAbsolute(basedir)
        ? basedir.replace(/\\\\/g, '/')
        : basedir
      const resolved = Module._resolveFilename(filePath, {
        id: filePath,
        filename: path.join(normalizedBasedir, 'package.json'),
        paths: Module._nodeModulePaths(normalizedBasedir),
      }, undefined, true)
      return { path: resolved }
    } catch (err) {
      if (err.code === 'MODULE_NOT_FOUND') {
        return { error: err.message }
      }
      throw err
    }
  }
  _sync(basedir, filePath) { return this.sync(basedir, filePath) }
  cloneWithOptions(newOptions) { return new this.constructor(newOptions) }
  clearCache() {}
}

module.exports = {
  ResolverFactory: NodeResolverFactory,
  EnforceExtension: { ERROR: 'error', WARN: 'warn', IGNORE: 'ignore' },
  ModuleType: {
    FILE: 'file', DIR: 'dir', EXTERN: 'extern',
    SHARED_LIBRARY: 'shared_library', NODE_MODULE: 'node_module', JSON: 'json'
  },
  builtins: Object.freeze([
    'assert', 'buffer', 'child_process', 'cluster', 'console', 'constants',
    'crypto', 'dgram', 'dns', 'domain', 'events', 'fs', 'http', 'https',
    'module', 'net', 'os', 'path', 'perf_hooks', 'process', 'punycode',
    'querystring', 'stream', 'string_decoder', 'sys', 'timers', 'tls',
    'tty', 'url', 'util', 'v8', 'vm', 'worker_threads',
    'node:assert', 'node:buffer', 'node:child_process', 'node:cluster',
    'node:console', 'node:constants', 'node:crypto', 'node:dgram',
    'node:dns', 'node:domain', 'node:events', 'node:fs', 'node:http',
    'node:https', 'node:module', 'node:net', 'node:os', 'node:perf_hooks',
    'node:process', 'node:punycode', 'node:querystring', 'node:stream',
    'node:string_decoder', 'node:sys', 'node:timers', 'node:tls',
    'node:tty', 'node:url', 'node:util', 'node:v8', 'node:vm',
    'node:worker_threads'
  ]),
  sync: (basedir, filePath) => {
    const factory = new NodeResolverFactory({ basedir })
    return factory.sync(basedir, filePath)
  },
  async: (basedir, filePath) => {
    const factory = new NodeResolverFactory({ basedir })
    return factory.sync(basedir, filePath)
  },
  clearCache: () => {}
}
`;

function applyPatches() {
  const unrsResolverPath = path.join(process.cwd(), 'node_modules', 'unrs-resolver');

  if (!fs.existsSync(unrsResolverPath)) {
    console.log('unrs-resolver not found, skipping patches');
    return;
  }

  // Write patched index.js
  fs.writeFileSync(
    path.join(unrsResolverPath, 'index.js'),
    PATCHED_INDEX_JS
  );
  console.log('Patched: node_modules/unrs-resolver/index.js');

  // Create shim file
  fs.writeFileSync(
    path.join(unrsResolverPath, 'unrs-shim.js'),
    SHIM_JS
  );
  console.log('Created: node_modules/unrs-resolver/unrs-shim.js');
}

applyPatches();